    Assert.assertTrue(b1.startsWith(b1.subSequence(0, 2)));
    Assert.assertFalse(b1.subSequence(0, 2).startsWith(b1));
    Assert.assertTrue(b1.endsWith(b1.subSequence(3, 5)));
