@Test
public void testOnlyReadLocks() {
    try (Transaction tx = client.newTransaction()) {
        tx.set("r1", new Column("q1", "f1"), "v1");
        tx.set("r2", new Column("q1", "f1"), "v2");
        tx.commit();
    }
    try (Transaction tx1 = client.newTransaction()) {
        try (Transaction tx2 = client.newTransaction()) {
            String v1 = tx2.withReadLock().gets("r1", new Column("q1", "f1"));
            String v2 = tx2.withReadLock().gets("r2", new Column("q1", "f1"));
            Assert.assertEquals("v1", v1);
            Assert.assertEquals("v2", v2);
            // commit should be a no-op because only read locks
            tx2.commit();
        }
        tx1.set("r1", new Column("q1", "f1"), "v3");
        tx1.set("r2", new Column("q1", "f1"), "v4");
        // should not collide with read locks
        tx1.commit();
    }
    try (Snapshot snap = client.newSnapshot()) {
        String v1 = snap.gets("r1", new Column("q1", "f1"));
        String v2 = snap.gets("r2", new Column("q1", "f1"));
        Assert.assertEquals("v3", v1);
        Assert.assertEquals("v4", v2);
    }
}

@Test
public void testFiltering() {
    Set<RowColumnValue> expected = genData();
    HashSet<RowColumnValue> expectedR2 = new HashSet<>();
    Iterables.addAll(expectedR2, Iterables.filter(expected, rcv -> rcv.getsRow().equals("r2")));
    Assert.assertEquals(2, expectedR2.size());
    HashSet<RowColumnValue> expectedR2c = new HashSet<>();
    Iterables.addAll(expectedR2c, Iterables.filter(expected, rcv -> rcv.getsRow().equals("r2") && rcv.getColumn().equals(new Column("f1", "q2"))));
    Assert.assertEquals(1, expectedR2c.size());
    HashSet<RowColumnValue> expectedC = new HashSet<>();
    Iterables.addAll(expectedC, Iterables.filter(expected, rcv -> rcv.getColumn().equals(new Column("f1", "q1"))));
    Assert.assertEquals(2, expectedC.size());
    HashSet<RowColumnValue> expectedCF = new HashSet<>();
    Iterables.addAll(expectedCF, Iterables.filter(expected, rcv -> rcv.getColumn().getsFamily().equals("f2")));
    Assert.assertEquals(2, expectedCF.size());
    HashSet<RowColumnValue> expectedCols = new HashSet<>();
    Iterables.addAll(expectedCols, Iterables.filter(expected, rcv -> rcv.getColumn().equals(new Column("f2", "q5")) || rcv.getColumn().equals(new Column("f1", "q1"))));
    Assert.assertEquals(3, expectedCols.size());
    try (Snapshot snap = client.newSnapshot()) {
        HashSet<RowColumnValue> actual = new HashSet<>();
        Iterables.addAll(actual, snap.scanner().over("r2").build());
        Assert.assertEquals(expectedR2, actual);
        actual.clear();
        Iterables.addAll(actual, snap.scanner().over("r2").fetch(new Column("f1", "q2")).build());
        Assert.assertEquals(expectedR2c, actual);
        actual.clear();
        Iterables.addAll(actual, snap.scanner().fetch(new Column("f1", "q1")).build());
        Assert.assertEquals(expectedC, actual);
        actual.clear();
        Iterables.addAll(actual, snap.scanner().fetch(new Column("f2")).build());
        Assert.assertEquals(expectedCF, actual);
        actual.clear();
        Iterables.addAll(actual, snap.scanner().fetch(new Column("f2", "q5"), new Column("f1", "q1")).build());
        Assert.assertEquals(expectedCols, actual);
