@Test
public void testZKAcls() throws Exception {
    // verify basic functionality works when password is set in ZK
    try (FluoClient client = FluoFactory.newClient(miniFluo.getClientConfiguration())) {
        try (Transaction tx = client.newTransaction()) {
            tx.set("node08", new Column("edge", "forward"), "node75");
            tx.commit();
        }
        miniFluo.waitForObservers();
        try (Snapshot snap = client.newSnapshot()) {
            Assert.assertEquals("node08", snap.gets("node75", new Column("edge", "reverese")));
        }
    }
    ZooKeeper zk = getZookeeper();
    // Verify oracle gc timestamp is visible w/o a password. The GC iterator that runs in Accumulo
    // tablet servers reads this.
    String ts = new String(zk.getData(ZookeeperPath.ORACLE_GC_TIMESTAMP, false, null), StandardCharsets.UTF_8);
    Assert.assertTrue(ts.matches("\\d+"));
    // the timestamp should be read only... trying to modify it should fail
    try {
        zk.delete(ZookeeperPath.ORACLE_GC_TIMESTAMP, -1);
        Assert.fail();
    } catch (NoAuthException nae) {
        // expected
    }
    try {
        zk.setData(ZookeeperPath.ORACLE_GC_TIMESTAMP, "foo".getBytes(), -1);
        Assert.fail();
    } catch (NoAuthException nae) {
        // expected
    }
    // try accessing a few random nodes in ZK... All should fail.
    for (String path : Arrays.asList(ZookeeperPath.ORACLE_SERVER, ZookeeperPath.CONFIG_SHARED, ZookeeperPath.CONFIG_FLUO_OBSERVERS2, ZookeeperPath.TRANSACTOR_NODES)) {
        try {
            zk.getData(path, false, null);
            Assert.fail();
        } catch (NoAuthException nae) {
            // expected
        }
        try {
            zk.getChildren(path, false);
            Assert.fail();
        } catch (NoAuthException nae) {
            // expected
        }
        try {
            zk.delete(path, -1);
            Assert.fail();
        } catch (NoAuthException nae) {
            // expected
        }
        try {
            zk.setData(path, "foo".getBytes(), -1);
            Assert.fail();
        } catch (NoAuthException nae) {
            // expected
        }
    }
    zk.close();
}

@Test
public void testCollisionLogging() throws Exception {
    Logger logger = Logger.getLogger("fluo.tx.collisions");
    StringWriter writer = new StringWriter();
    WriterAppender appender = new WriterAppender(new PatternLayout("%p, %m%n"), writer);
    Level level = logger.getLevel();
    boolean additivity = logger.getAdditivity();
    try {
        logger.setLevel(Level.TRACE);
        logger.setAdditivity(false);
        logger.addAppender(appender);
        try (LoaderExecutor le = client.newLoaderExecutor()) {
            for (int i = 0; i < 20; i++) {
                le.execute(new SimpleBinaryLoader());
                le.execute(new TriggerLoader(i));
            }
        }
        miniFluo.waitForObservers();
    } finally {
        logger.removeAppender(appender);
        logger.setAdditivity(additivity);
        logger.setLevel(level);
    }
    String logMsgs = writer.toString();
    logMsgs = logMsgs.replace('\n', ' ');
    Assert.assertFalse(logMsgs.contains("TriggerLoader"));
    String pattern;
