    pattern = ".*txid: (\\d+) trigger: \\d+ stat count  \\d+";
    pattern += ".*txid: \\1 class: org.apache.fluo.integration.log.LogIT\\$TestObserver";
    pattern += ".*txid: \\1 collisions: \\Q[all=[stat count ]]\\E.*";
